  const r = await fetch(u + jalur, { method, headers: { 'Content-Type': 'application/json', ...(token && { Authorization: `Bearer ${token}` }) }, body: body && JSON.stringify(body) });
  return { status: r.status, isi: r.status === 204 ? null : await r.json() };
};
